# Hand-written wrapper (NOT generated by savvy-cli). `sz_run_experiment_raw()`
# is the savvy-generated binding, defined in R/000-wrappers.R; this wrapper
# gives it R-native default arguments (savvy has no way to express a non-NULL
# default for a required argument in the generated signature).

#' Run a sezgi experiment spec across algorithms x problems x instances x
#' seeds x budgets.
#'
#' Mirrors py-sezgi's `run_experiment()`: `journal = NULL` runs directly
#' (in parallel or sequentially, per `parallel`); a non-`NULL` `journal`
#' path runs through the checkpoint executor, which resumes from -- and
#' appends to -- an existing journal file at that path.
#'
#' @param spec_toml Experiment spec as TOML. Schema (see
#'   `crates/bench/src/experiment.rs`): top-level `name` (string), `seeds`
#'   (integer array), `budgets` (integer array); one or more `[[algorithms]]`
#'   tables, each with a `name` and either `preset = \{ kind = "...",
#'   pop_size = ... \}` (pop_size optional/ignored for dim-linked presets:
#'   `lshade`, `cmaes_ipop`, `nelder_mead`, `sa`) or `spec_toml = "..."`; one
#'   or more `[[problems]]` tables, each with `suite = "bbob"`, `fid`
#'   (integer), `dim` (integer), `instances` (integer array).
#' @param journal Optional path to a checkpoint journal file (JSONL). When
#'   given, results are loaded from and appended to this file, and re-running
#'   with the same file resumes without re-running completed cells.
#' @param parallel Whether to run in parallel via rayon (default `TRUE`).
#'   Results are bit-identical to the sequential (`FALSE`) run.
#' @param threads Optional rayon thread-pool size (`NULL` uses rayon's
#'   default).
#' @param log_dir Optional directory: when given, every run this call
#'   actually EXECUTES is also logged in IOH-profiler format under that
#'   directory (a run resumed from `journal` was executed in a PRIOR call
#'   and is never re-logged). Read back with `sz_read_ioh_records()`.
#' @returns A data.frame with one row per run and columns `algo`, `fid`,
#'   `dim`, `instance`, `seed`, `budget`, `suite`, `best_f`, `f_opt`,
#'   `evals`.
#' @export
sz_run_experiment <- function(spec_toml, journal = NULL, parallel = TRUE, threads = NULL,
                               log_dir = NULL) {
  sz_run_experiment_raw(spec_toml, parallel, journal, threads, log_dir)
}

#' Build a `sezgi_stats`-shaped results matrix for one `budget` from a
#' `sz_run_experiment()` data.frame.
#'
#' Mirrors py-sezgi's `results_matrix()`.
#'
#' @param df A data.frame as returned by `sz_run_experiment()` (columns
#'   `algo`, `fid`, `dim`, `instance`, `seed`, `budget`, `suite`, `best_f`,
#'   `f_opt`, `evals`). `suite` is optional -- a data.frame without it (e.g.
#'   from before this column existed) is treated as all-BBOB.
#' @param budget Only rows with this budget are used.
#' @param aggregate How to combine a (problem, algorithm) cell's per-seed
#'   gaps (`best_f - f_opt`) into one number: `"mean"` or `"median"`.
#' @returns A named list with `algo_names` (character vector),
#'   `problem_labels` (character vector, `f\{fid\}d\{dim\}i\{instance\}` for
#'   BBOB rows, `\{short\}-f\{fid\}d\{dim\}i\{instance\}` for any other
#'   suite, ordered by first appearance in `df`), and `matrix` (numeric
#'   matrix, rows = problems, columns = algorithms; `matrix[i, j]` is the
#'   aggregated gap of `algo_names[j]` on `problem_labels[i]`). Errors if a
#'   (problem, algorithm) pair present for one algorithm/problem is missing
#'   for another at this budget (an incomplete experiment).
#' @export
sz_results_matrix <- function(df, budget, aggregate = "mean") {
  suite <- if (is.null(df$suite)) rep("sezgi-bbob", nrow(df)) else df$suite
  sz_results_matrix_raw(df$algo, df$fid, df$dim, df$instance, df$seed, df$budget,
                         suite, df$best_f, df$f_opt, df$evals, budget, aggregate)
}

#' Build one paper-package statistics list PER DISTINCT BUDGET present in a
#' `sz_run_experiment()` data.frame, in ascending budget order.
#'
#' Mirrors py-sezgi's `per_budget_packages()`. Piotrowski et al. (2025) show
#' algorithm rankings on benchmark comparisons can flip depending on which
#' evaluation budget is examined, so this makes multi-budget reporting the
#' default rather than a single, arbitrarily-chosen budget's report:
#' compare algorithms per budget, never pooled across budgets.
#'
#' @param df A data.frame as returned by `sz_run_experiment()`. `suite` is
#'   optional -- a data.frame without it is treated as all-BBOB (see
#'   `sz_results_matrix()`).
#' @param rope Region of practical equivalence half-width (>= 0) for the
#'   Bayesian signed-rank test, forwarded to every budget's package.
#'   Default 0.
#' @param samples Number of Monte Carlo samples per pair. Default 20000.
#' @param seed Master RNG seed, forwarded to every budget's package.
#'   Default 1.
#' @param aggregate How to combine a (problem, algorithm) cell's per-seed
#'   gaps: `"mean"` or `"median"`. Default `"mean"`.
#' @returns A named list, one entry per distinct budget in ascending order,
#'   named by the budget (as a string); each value has exactly the shape
#'   `sz_stats_paper_package()` returns.
#' @export
sz_per_budget_packages <- function(df, rope = 0, samples = 20000, seed = 1, aggregate = "mean") {
  suite <- if (is.null(df$suite)) rep("sezgi-bbob", nrow(df)) else df$suite
  sz_per_budget_packages_raw(df$algo, df$fid, df$dim, df$instance, df$seed, df$budget,
                              suite, df$best_f, df$f_opt, df$evals, rope, samples, seed, aggregate)
}
